ipmi_entity_t * ipmi_entity_lookup ( ipmi_handle_t * ihp , uint8_t type , uint8_t instance ) { ipmi_entity_t search ; ipmi_entity_impl_t * eip ; search . ie_type = type ; search . ie_instance = instance ; if ( ( eip = ipmi_hash_lookup ( ihp -> ih_entities , & search ) ) == NULL ) { ( void ) ipmi_set_error ( ihp , EIPMI_NOT_PRESENT , NULL ) ; return ( NULL ) ; } return ( & eip -> ie_entity ) ; } 